use std::{fs,process::Command,sync::{Arc,Barrier,atomic::{AtomicUsize,Ordering}},thread};
fn main(){if std::env::args().any(|a| a=="--child"){return;}
let source=std::env::current_exe().unwrap();let root=source.parent().unwrap().join(format!("copies-{}",std::process::id()));fs::create_dir(&root).unwrap();let start=Arc::new(Barrier::new(8));let fails=Arc::new(AtomicUsize::new(0));let mut joins=vec![];
for id in 0..8{let (start,fails,source,root)=(start.clone(),fails.clone(),source.clone(),root.clone()); joins.push(thread::spawn(move||{let exe=root.join(format!("worker-{id}"));start.wait();for round in 0..100{fs::copy(&source,&exe).unwrap();match Command::new(&exe).arg("--child").output(){Ok(output)=>assert!(output.status.success()),Err(error)=>{fails.fetch_add(1,Ordering::Relaxed);println!("worker={id} round={round} error={error:?}");}}}}));}for join in joins{join.join().unwrap();}println!("failed={} total=800",fails.load(Ordering::Relaxed));fs::remove_dir_all(root).unwrap();}
